<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Ball Playground</title>
<style>
  :root { color-scheme: dark; }
  html, body {
    margin: 0;
    height: 100%;
    background: #12141c;
    color: #e6e6e6;
    font-family: -apple-system, "Segoe UI", Roboto, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
  }
  h1 {
    font-size: 1.1rem;
    font-weight: 500;
    letter-spacing: 0.03em;
    color: #9fb4ff;
    margin: 0;
  }
  #sim {
    background: radial-gradient(circle at 50% 0%, #1c2030, #0a0b10);
    border: 1px solid #2a2f45;
    border-radius: 12px;
    box-shadow: 0 0 40px rgba(80, 100, 255, 0.15), inset 0 0 60px rgba(0,0,0,0.4);
    cursor: crosshair;
    touch-action: none;
  }
  .controls {
    display: flex;
    gap: 10px;
  }
  button {
    background: #1e2230;
    color: #e6e6e6;
    border: 1px solid #3a3f5a;
    border-radius: 8px;
    padding: 8px 18px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.15s, transform 0.1s;
  }
  button:hover { background: #2a2f45; }
  button:active { transform: scale(0.96); }
  #play.paused { color: #ffb454; border-color: #7a5a2a; }
</style>
</head>
<body>

<h1>Bouncing Ball Playground</h1>
<canvas id="sim" width="600" height="450"></canvas>
<div class="controls">
  <button id="drop">Drop Ball</button>
  <button id="play">Pause</button>
  <button id="clear">Clear</button>
</div>

<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 0.5;
  const RESTITUTION = 0.78;

  const COLORS = [
    '#ff6b6b', '#feca57', '#48dbfb', '#1dd1a1',
    '#ff9ff3', '#54a0ff', '#f368e0', '#00d2d3'
  ];

  let balls = [];
  let running = true;
  let colorIdx = 0;

  function makeBall(x, y, vx, vy, r) {
    r = r || (12 + Math.random() * 14);
    x = Math.min(Math.max(x, r), W - r);
    y = Math.min(Math.max(y, r), H - r);
    const color = COLORS[colorIdx % COLORS.length];
    colorIdx++;
    return { x, y, vx: vx || 0, vy: vy || 0, r, color };
  }

  function addBall(x, y, vx, vy, r) {
    const b = makeBall(x, y, vx, vy, r);
    balls.push(b);
    draw();
    return b;
  }

  function clearBalls() {
    balls = [];
    draw();
  }

  function step(dt) {
    dt = dt === undefined ? 1 : dt;
    for (const b of balls) {
      b.vy += GRAVITY * dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = -b.vx * RESTITUTION;
      } else if (b.x + b.r > W) {
        b.x = W - b.r;
        b.vx = -b.vx * RESTITUTION;
      }

      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = -b.vy * RESTITUTION;
      } else if (b.y + b.r > H) {
        b.y = H - b.r;
        b.vy = -b.vy * RESTITUTION;
      }
    }
    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    for (const b of balls) {
      ctx.beginPath();
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(0.15, b.color);
      grad.addColorStop(1, b.color);
      ctx.fillStyle = grad;
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.lineWidth = 1;
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  function loop() {
    if (running) {
      step(1);
    }
    requestAnimationFrame(loop);
  }

  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    addBall(x, y, (Math.random() - 0.5) * 6, -2);
  });

  document.getElementById('drop').addEventListener('click', () => {
    addBall(
      W / 2 + (Math.random() - 0.5) * 100,
      40 + Math.random() * 40,
      (Math.random() - 0.5) * 8,
      0
    );
  });

  const playBtn = document.getElementById('play');
  playBtn.addEventListener('click', () => {
    running = !running;
    playBtn.textContent = running ? 'Pause' : 'Play';
    playBtn.classList.toggle('paused', !running);
  });

  document.getElementById('clear').addEventListener('click', clearBalls);

  // seed a couple of balls
  addBall(W * 0.35, 60, 3, 0);
  addBall(W * 0.65, 100, -2, 0);

  window.sim = {
    w: W,
    h: H,
    balls: () => balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r })),
    addBall: (x, y, vx, vy, r) => {
      const b = addBall(x, y, vx, vy, r);
      return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r };
    },
    clear: clearBalls,
    step: step
  };

  draw();
  requestAnimationFrame(loop);
})();
</script>

</body>
</html>
